use vstd::prelude::*;

verus! {

    // Compute the broadcasted length: the maximum of the two lengths.
    spec fn broadcast_len(a: Seq<i8>, b: Seq<i8>) -> nat {
        let la = a.len();
        let lb = b.len();
        if la >= lb { la } else { lb }
    }

    // Broadcast a up to length = broadcast_len(a,b).
    spec fn broadcast_seq_a(a: Seq<i8>, b: Seq<i8>) -> Seq<i8>
        requires a.len() >= 1 && b.len() >= 1
        ensures result.len() == broadcast_len(a, b)
        ensures forall(|i: nat| i < result.len() ==>
            (if a.len() == 1 { a[0] } else { a[i] }) == result[i])
    {
        Seq::new(|i: nat|
            ensures i < broadcast_len(a, b);
            if a.len() == 1 { a[0] } else { a[i] }
        )
    }

    // Broadcast b up to length = broadcast_len(a,b).
    spec fn broadcast_seq_b(a: Seq<i8>, b: Seq<i8>) -> Seq<i8>
        requires a.len() >= 1 && b.len() >= 1
        ensures result.len() == broadcast_len(a, b)
        ensures forall(|i: nat| i < result.len() ==>
            (if b.len() == 1 { b[0] } else { b[i] }) == result[i])
    {
        Seq::new(|i: nat|
            ensures i < broadcast_len(a, b);
            if b.len() == 1 { b[0] } else { b[i] }
        )
    }

    // Broadcast two non‐empty, compatible vectors a and b.
    // Compatibility means: either same length, or one of them has length 1.
    fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>)
        -> (ra: Vec<i8>, rb: Vec<i8>)
        requires
            a.len() >= 1 && b.len() >= 1,
            a.len() == b.len() || a.len() == 1 || b.len() == 1,
        ensures
            // The resulting vectors, viewed as sequences, match the spec.
            ra@ == broadcast_seq_a(a@, b@) &&
            rb@ == broadcast_seq_b(a@, b@)
    {
        // Compute the runtime length = max(a.len(), b.len()).
        let len: usize = if a.len() >= b.len() { a.len() } else { b.len() };

        let mut ra: Vec<i8> = Vec::new();
        let mut rb: Vec<i8> = Vec::new();
        let mut i: usize = 0;

        // Build up ra and rb by pushing one element at a time.
        while i < len
            invariant
                // i is the number of elements already pushed
                i <= len,
                ra.len() == i,
                rb.len() == i,
                // For all j < i, ra[j] and rb[j] agree with the spec at index j
                forall(|j: nat| j < i as nat ==>
                    ra[j] == broadcast_seq_a(a@, b@)[j]
                ),
                forall(|j: nat| j < i as nat ==>
                    rb[j] == broadcast_seq_b(a@, b@)[j]
                ),
            decreases len - i,
        {
            // Decide the next element by broadcasting rules.
            let ai: i8 = if a.len() == 1 { a[0] } else { a[i] };
            let bi: i8 = if b.len() == 1 { b[0] } else { b[i] };

            ra.push(ai);
            rb.push(bi);
            i += 1;
        }

        // At the end, ra.len() == len and rb.len() == len, and by the invariant
        // they match the spec everywhere.
        (ra, rb)
    }

}

